// Unique Vintage Processor — static make-up for the processed top band (generated by UVPHarness calibharm)
// Keeps the band's level steady at extreme drive so heavy settings don't simply dull the top end.
#pragma once

namespace uvp::hmk
{
constexpr int kSteps = 23; // amount 0..11 in 0.5 steps
inline const float (&table())[3][kSteps]
{
    static const float t[3][kSteps] = {
        { 0.00f, 0.16f, 0.16f, 0.16f, 0.16f, 0.15f, 0.14f, 0.13f, 0.12f, 0.14f, 0.21f, 0.23f, 0.04f, -0.27f, -0.31f, 0.11f, 0.91f, 3.14f, 5.79f, 8.73f, 9.00f, 9.00f, 9.00f },
        { 0.00f, 0.11f, 0.32f, 0.41f, 0.30f, 0.10f, 0.03f, 0.12f, 0.25f, 0.43f, 0.68f, 1.00f, 1.41f, 1.92f, 2.52f, 3.23f, 4.05f, 5.94f, 8.19f, 9.00f, 9.00f, 9.00f, 9.00f },
        { 0.00f, 0.54f, 0.39f, 0.23f, 0.06f, -0.12f, -0.31f, -0.52f, -0.68f, -0.74f, -0.61f, -0.26f, 0.34f, 1.15f, 2.10f, 3.11f, 4.10f, 6.41f, 9.00f, 9.00f, 9.00f, 9.00f, 9.00f }
    };
    return t;
}
inline float makeupDb (int mode, float amount) noexcept
{
    const auto& t = table();
    mode = mode < 0 ? 0 : (mode > 2 ? 2 : mode);
    float x = amount * 2.0f;
    x = x < 0.0f ? 0.0f : (x > (float) (kSteps - 1) ? (float) (kSteps - 1) : x);
    const int i0 = (int) x, i1 = i0 + 1 < kSteps ? i0 + 1 : i0;
    const float fr = x - (float) i0;
    return t[mode][i0] + fr * (t[mode][i1] - t[mode][i0]);
}
} // namespace uvp::hmk
